mapper.sql:
a.tenant_id=#{tenant} AND a.factory_code=#{factory} AND a.del_flag='0'
AND a.task_code=#{q.taskCode}
AND a.produce_task_code=#{q.produceTaskCode}
AND a.code=#{q.arrangeCode}
AND a.id=CAST(#{q.arrangeId} AS BIGINT)
AND a.workshop_code=#{q.workshopCode}
AND a.shift_code=#{q.shiftCode}
AND a.status=#{q.status}
AND a.execution_template_code=#{q.executionTemplateCode}
AND a.execution_template_version=#{q.executionTemplateVersion}

    AND POSITION(CONCAT(',',#{q.workerCode},',') IN CONCAT(',',REPLACE(a.worker_code,' ',''),',')) > 0


    AND (a.actual_worksite_code=#{q.worksiteCode}
    OR POSITION(CONCAT(',',#{q.worksiteCode},',') IN CONCAT(',',REPLACE(a.worksite_codes,' ',''),',')) > 0)

AND  >= #{q.startTime}
AND  < #{q.endTime}
